import * as React from "react"

import { cn } from "@/lib/utils"

// Control Room AvatarGroup: overlapping crew badges with an overflow
// counter chip in the same square ID-tile material.

export interface AvatarGroupProps
  extends React.HTMLAttributes<HTMLDivElement> {
  max?: number
}

const AvatarGroup = React.forwardRef<HTMLDivElement, AvatarGroupProps>(
  ({ className, max, children, ...props }, ref) => {
    const childArray = React.Children.toArray(children)
    const visible = max ? childArray.slice(0, max) : childArray
    const overflow = max ? childArray.length - max : 0

    return (
      <div ref={ref} className={cn("flex -space-x-2", className)} {...props}>
        {visible}
        {overflow > 0 && (
          <div className="relative flex h-10 w-10 items-center justify-center rounded-sm ring-1 ring-border bg-secondary text-xs font-semibold text-muted-foreground">
            +{overflow}
          </div>
        )}
      </div>
    )
  }
)
AvatarGroup.displayName = "AvatarGroup"

export { AvatarGroup }
